// ============================================================
// Transformation Notion → products.json
// ============================================================

const notionProducts = $input.first().json;
const allImages = $('🖼 Lire PRODUIT_IMAGES').all().map(i => i.json);

// Index images par produit_id
const imagesByProduct = {};
for (const img of allImages) {
  const produitRelation = img.properties?.produit?.relation;
  if (!produitRelation || produitRelation.length === 0) continue;
  const prodId = produitRelation[0].id;
  if (!imagesByProduct[prodId]) imagesByProduct[prodId] = [];
  imagesByProduct[prodId].push({
    path: img.properties?.github_path?.rich_text?.[0]?.plain_text || '',
    ordre: img.properties?.ordre?.number || 99,
    alt: img.properties?.alt_text?.rich_text?.[0]?.plain_text || ''
  });
}

// Trier images par ordre
for (const key of Object.keys(imagesByProduct)) {
  imagesByProduct[key].sort((a, b) => a.ordre - b.ordre);
}

// Transformer chaque produit Notion
const products = $input.all().map(item => {
  const p = item.json.properties;
  const notionId = item.json.id;
  const idNum = p.id_num?.number || 0;

  // Images : depuis PRODUIT_IMAGES ou fallback sur id_num
  const images = imagesByProduct[notionId]
    ? imagesByProduct[notionId].map(img => img.path)
    : [`/images/${idNum}.jpg`];

  return {
    id: idNum,
    notion_id: notionId,
    sku: p.sku?.rich_text?.[0]?.plain_text || '',
    slug: p.slug?.rich_text?.[0]?.plain_text || '',
    name: p.nom?.title?.[0]?.plain_text || '',
    type: p.type?.select?.name || '',
    etat: p.etat?.select?.name || 'Neuf',
    description_courte: p.description_courte?.rich_text?.[0]?.plain_text || '',
    description_longue: p.description_longue?.rich_text?.[0]?.plain_text || '',
    price: p.prix_public?.number || 0,
    stock: p.stock_publie?.number ?? p.stock_initial?.number ?? 0,
    tag: p.tag?.select?.name || null,
    sym: p.sym?.rich_text?.[0]?.plain_text || '◇',
    actif: p.visible_site?.checkbox ?? true,
    variant_group_id: p.variant_group_id?.rich_text?.[0]?.plain_text || null,
    ordre: p.ordre_affichage?.number || 99,
    images
  };
});

// Construire le JSON final
const output = {
  _meta: {
    generated_at: new Date().toISOString(),
    generated_by: 'n8n W1 — Sync Produits',
    count: products.length,
    version: '1.0'
  },
  products
};

return [{ json: { content: JSON.stringify(output, null, 2) } }];

// Encoder le contenu en base64 pour l'API GitHub
const content = $input.first().json.content;
const encoded = Buffer.from(content).toString('base64');
return [{ json: { content_b64: encoded, content_raw: content } }];
